float funkcja(long n);

float funkcja2(long n)
{
	if (n == 1)
		return 1;
	if (n == 2)
		return 2;

	return (1.2f - funkcja(n - 1)) / n;

}

int main()
{
	float ret2 = funkcja2(10);
	float ret = funkcja(10);
	printf("%f %f", ret, ret2);
	return 0;
}

