#include <stdio.h>

void przestaw(int tabl[], int n);

int main()
{
  int tab[] = { 0,1,2,5,5,5,4,3,2,1 };
  int n = sizeof(tab) / sizeof(int);

  printf("Przed: ");
  for (int i = 0; i < n; i++) {
    printf("%d ", tab[i]);
  }
  printf("\n\n");

  int rozmiar = n;
  while (n > 1) 
  {
    for (int i = 0; i < (n - 1); i++) {
      przestaw(tab, n);
    }
    --n;
  }

  n = rozmiar;
  printf("Po   : ");
